-- ============================================================================
-- FC6: Heat Exchange & Cooling joins the catalog, the SIXTH Facilities course.
--
-- Catalog row (module 'facilities'; path_order 44, directly above FC5 at 43,
-- FC4 gasprocessing at 42, FC3 rotating at 41, FC2 linesizing at 40 and FC1
-- separation at 39; prereq_slug NULL, the carried-over answer "no hard
-- prerequisite inside a module") plus the three capstones and their eighteen
-- graded fields, generated by tools/course-waves/heattransfer/gen_course.py
-- from fields.json, precision.json and the capstone constants in
-- fc6_fields_capstone.mjs. Deep seeds are three separate migrations; the
-- go-live is a fifth and is HELD until a NextGen production upload carries the
-- route /dashboard/apps/heattransfer, because the 78 lessons, the teaching lab
-- (heattransferLab.js) and its three explorer panels ship in the zip and not in
-- this database.
--
-- THE ONE SENTENCE THE COURSE IS. An exchanger is four questions in a chain and
-- the chain is a LOOP, and the discipline is knowing which of the numbers in
-- front of you the engine COMPUTED, which one you CHOSE, and which one it
-- declined to invent.
--
-- THE ENGINE. engines/facilities/heatTransfer.js (the capacity rate, the energy
-- balance and the refusals that protect it, the log mean and its two pairings,
-- the P and R groups, Bowman's correction factor and the equivalent
-- single-shell P for shells in series, the overall coefficient assembled from
-- five named resistances with the controlling one and its margin, the area, the
-- tube count with its two roundings, effectiveness and NTU in both directions,
-- the air cooler and its hot-day rating at fixed UA). This module IMPORTS
-- NOTHING AT ALL, so its family is the engine, its golden, its jest suite, its
-- oracle and its findings record. Vendored at engines e4377b3, the FC6-0 repair
-- wave, sha-identical and proved three independent ways.
--
-- NOTHING GRADED DEPENDS ON A HELD OR FITTED QUANTITY, and each one is
-- neutralised by CONSTRUCTION rather than by hope. The five fitted constants
-- (Dittus-Boelter's 0.023, 0.8 and 0.4, the Sieder-Tate 0.14 and the laminar
-- Nusselt 3.66) live in tubeSideFilm and nowhere else, and no capstone calls
-- it: AMENAM is handed its overall coefficient and UBIT STATES both film
-- coefficients. The held bundle table sets only a bundle diameter and a shell
-- diameter, and no graded field reads either. The held cross-flow correction
-- sets only the design AREA of an air cooler, and no graded field reads it; the
-- hot day is rated from the DEFINITION of effectiveness at fixed UA and fixed
-- air mass, so it assumes no arrangement and needs no F. The held fan constant
-- sets only a fan and motor horsepower, and OKWORI states its own static
-- pressure, fan efficiency and motor efficiency so none of the three defaults
-- is even read. The held wall conductivity default names no material, and UBIT
-- states its own. The go-live asserts all of it, on the labels and again on the
-- values.
--
-- THE CAPSTONE GRADES WHAT THE COURSE TEACHES A READER TO GET RIGHT: that a
-- specified outlet makes the duty and the other outlet an ANSWER rather than a
-- condition, that a tube count rounds TWICE and the second rounding moves the
-- surface margin, that a shell pass is bought through an equivalent
-- single-shell P and not through F directly, that a controlling resistance is a
-- verdict with a MARGIN, and that a hot day is rated at fixed UA with an
-- effectiveness taken from its definition rather than from an arrangement.
-- All eighteen graded values were swept against every number the digest prints
-- and against every number handed to a learner in a prompt, at each field's own
-- shipped tolerance: 0 collisions, and 0 pairwise.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('heattransfer', 'Heat Exchange & Cooling', 'facilities', 44, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'heattransfer', 'beginner', 'associate',
  'AMENAM, a crude cooler on a flow station read from its energy balance to its tube count',
  'One exchanger, end to end, in closed form',
  'AMENAM, the crude cooler on a flow station. The hot crude runs at 62000 lb an hour with a heat capacity of 0.58 Btu per lb degF, entering at 328 degF and specified to leave at 214 degF. The cooling water runs at 91000 lb an hour with a heat capacity of 0.97 Btu per lb degF and enters at 119 degF, and its outlet is not specified. The unit is counter-current. The study was given an overall coefficient of 126 Btu per hr ft2 degF, so no film is computed and the correction factor is 1. The bundle the fabricator quoted is 0.875 inch outside diameter tubes, 18 ft long, on a 30 degree layout in 2 tube passes, with a bundle-to-shell clearance of 2.75 inches. Report six values: the duty the specified hot outlet sets, the cold outlet that duty implies, the counter-current log mean, the outside surface the duty needs, the outside surface one tube carries, and the percentage by which the whole bundle overshoots the required surface once the count is rounded up to a whole multiple of the passes. The duty in Btu an hour, to four decimals. Temperatures in degF, surfaces in ft2 and the margin in percent, to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','amenam_duty_btu_hr', 'label','The duty the specified hot outlet sets', 'unit','Btu/hr', 'expected',4099440, 'tol',0.01),
    jsonb_build_object('key','amenam_cold_outlet_f', 'label','The cold outlet that duty implies', 'unit','degF', 'expected',165.44205279256826, 'tol',1e-06),
    jsonb_build_object('key','amenam_lmtd_f', 'label','The counter-current log mean driving force', 'unit','degF', 'expected',125.76931159982445, 'tol',1e-06),
    jsonb_build_object('key','amenam_area_ft2', 'label','The outside surface the duty needs', 'unit','ft2', 'expected',258.6898002492009, 'tol',1e-06),
    jsonb_build_object('key','amenam_area_per_tube_ft2', 'label','The outside surface one tube carries', 'unit','ft2', 'expected',4.123340357836604, 'tol',1e-06),
    jsonb_build_object('key','amenam_area_margin_pct', 'label','The surface the pass-count rounding overshoots by', 'unit','percent', 'expected',2.011669052018527, 'tol',5e-07)
  )
),
(
  'heattransfer', 'intermediate', 'professional',
  'UBIT, a shell-and-tube train read as a correction factor and then as five resistances',
  'What a shell buys, and which resistance is in charge',
  'UBIT, the shell-and-tube train. The four terminals are a hot stream entering at 405 degF and leaving at 265 degF against a cold stream entering at 135 degF and leaving at 233 degF. Read the correction factor first at ONE shell pass, then take the same duty into TWO shells in series. The coefficient is assembled from five named resistances on a tube of 0.875 inch outside diameter and 0.729 inch inside diameter. Both film coefficients are STATED as conditions of this study, 265 Btu per hr ft2 degF outside and 1120 inside, and so is the wall conductivity of 29 Btu per hr ft degF, so nothing here is looked up. The fouling allowances are 0.0015 hr ft2 degF per Btu outside and 0.0025 inside. Report six values: the correction factor at one shell pass, the equivalent single-shell P at two shells in series, the clean overall coefficient, the dirty one, what the two fouling allowances cost as a percentage of the clean coefficient, and how far the controlling resistance leads the runner up as a percentage of itself. Correction factors and equivalent P as a fraction, coefficients in Btu per hr ft2 degF and both percentages in percent, all to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ubit_f_correction', 'label','The correction factor at one shell pass', 'unit','fraction', 'expected',0.8879617104201317, 'tol',5e-07),
    jsonb_build_object('key','ubit_p1_two_shells', 'label','The equivalent single-shell P at two shells in series', 'unit','fraction', 'expected',0.23359328643184238, 'tol',5e-07),
    jsonb_build_object('key','ubit_u_clean', 'label','The clean overall coefficient, referred to the outside tube surface', 'unit','Btu/hr.ft2.F', 'expected',197.05374899995743, 'tol',1e-06),
    jsonb_build_object('key','ubit_u_dirty', 'label','The dirty overall coefficient, referred to the same outside surface', 'unit','Btu/hr.ft2.F', 'expected',104.43380596479474, 'tol',1e-06),
    jsonb_build_object('key','ubit_fouling_penalty_pct', 'label','What the two fouling allowances cost that coefficient', 'unit','percent', 'expected',47.002375496638074, 'tol',1e-06),
    jsonb_build_object('key','ubit_controlling_margin_pct', 'label','How far the controlling resistance leads the next one', 'unit','percent', 'expected',20.48182441700959, 'tol',1e-06)
  )
),
(
  'heattransfer', 'advanced', 'expert',
  'OKWORI, an air cooler bay read at its design point and again on the afternoon it is judged on',
  'The hot day, rated at fixed UA and assuming no arrangement',
  'OKWORI, the air cooler bay. It was bought on a duty of 26400000 Btu an hour, taking the process from 268 degF to 172 degF against 93 degF design ambient air that rises 27 degF, at an overall coefficient of 4.85 Btu per hr ft2 degF. It is a forced-draft bay at a barometric pressure of 13.9 psia, and it states its own machine numbers rather than taking any default: a fan static pressure of 0.78 inches of water, a fan efficiency of 0.68 and a motor efficiency of 0.94. The afternoon it is judged on is 113 degF ambient, and it is rated there at the SAME UA and the SAME air mass, with the effectiveness taken from its definition so that no arrangement and no correction factor is assumed anywhere. Report six values: the design log mean of the bay, the effectiveness at the design point taken from its definition, the capacity ratio, the UA the bay holds, the NTU at that fixed UA, and where the process actually leaves on the hot afternoon. The UA in Btu per hr degF, to four decimals. The log mean and the process outlet in degF, and the effectiveness, the capacity ratio and the NTU as fractions, to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','okwori_design_lmtd_f', 'label','The design log mean of the bay', 'unit','degF', 'expected',109.91384293081067, 'tol',1e-06),
    jsonb_build_object('key','okwori_design_effectiveness', 'label','Effectiveness at the design point, taken from its definition', 'unit','fraction', 'expected',0.5485714285714286, 'tol',5e-07),
    jsonb_build_object('key','okwori_capacity_ratio', 'label','The capacity ratio of the bay', 'unit','fraction', 'expected',0.28125, 'tol',5e-07),
    jsonb_build_object('key','okwori_ua_btu_hr_f', 'label','The surface the bay holds on the hot day, as UA', 'unit','Btu/hr.F', 'expected',240188.12640932275, 'tol',0.01),
    jsonb_build_object('key','okwori_hotday_ntu', 'label','NTU at that fixed UA', 'unit','fraction', 'expected',0.8734113687611736, 'tol',5e-07),
    jsonb_build_object('key','okwori_hotday_process_out_f', 'label','Where the process actually leaves on the hot afternoon', 'unit','degF', 'expected',182.97142857142856, 'tol',1e-06)
  )
)
on conflict (app_slug, tier) do nothing;
